from __future__ import absolute_import

from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v25r1, v25r2


class Diagnostic(v25r2.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._debug_tracing = DebugTracingPage(driver)
        self._diagnostic_check = DiagnosticCheckPage(driver)


class DebugTracingPage(v25r1.diagnostic.DebugTracingPage):

    def __init__(self, driver):
        super(DebugTracingPage, self).__init__(driver)
        self._view_panel = DebugTracingPageViewPanel(driver)

    def configure_iq_capture(
            self,
            enable_capture_on="Event",
            capture_from="BBU",
            profile=None,
            ul_subcell_index_list=None,
            dl_subcell_index_list=None,
            lte_ul_cell_ids=None,
            lte_dl_cell_ids=None,
            buffer_cycle=None,
            capture_frame_offset=None,
            radio_configurations=None
    ):
        self._detail_panel.close_details_panel()
        return self._view_panel.configure_iq_capture(
            enable_capture_on=enable_capture_on,
            capture_from=capture_from,
            profile=profile,
            ul_subcell_index_list=ul_subcell_index_list,
            dl_subcell_index_list=dl_subcell_index_list,
            lte_ul_cell_ids=lte_ul_cell_ids,
            lte_dl_cell_ids=lte_dl_cell_ids,
            buffer_cycle=buffer_cycle,
            capture_frame_offset=capture_frame_offset,
            radio_configurations=radio_configurations)


class DebugTracingPageViewPanel(v25r1.diagnostic.DebugTracingPageViewPanel):

    ENABLE_CAPTURE_ON_RADIO_XPATH_TEMPLATE = ("//div[div[text()='Enable capture on:']]//"
                                              "label[text()='{}']/preceding-sibling::input")

    CAPTURE_FROM_RADIO_XPATH_TEMPLATE = ("//div[div[text()='Capture from:']]//"
                                         "label[text()='{}']/preceding-sibling::input")

    PROFILE_BUTTON_XPATH = "//div[div[text()='Profile:']]//button"

    PROFILE_DROPDOWN_OPTION_XPATH = '//span[@class="ng-item ng-binding"]'

    def configure_iq_capture(
            self,
            enable_capture_on="Event",
            capture_from="BBU",
            profile=None,
            ul_subcell_index_list=None,
            dl_subcell_index_list=None,
            lte_ul_cell_ids=None,
            lte_dl_cell_ids=None,
            buffer_cycle=None,
            capture_frame_offset=None,
            radio_configurations=None
    ):
        elem = self.driver.find_element_by_xpath(self._L1_IQ_CAPTURE_XPATH)
        self._scroll_elem_into_view(elem, "start", "nearest")
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_operation(self._COMPONENT_TYPE, self._CONFIGURE)

        self._select_enable_capture_on_option(enable_capture_on)
        self._configure_with_capture_on_event(capture_from,
                                              ul_subcell_index_list,
                                              dl_subcell_index_list,
                                              buffer_cycle,
                                              capture_frame_offset,
                                              radio_configurations,
                                              profile)

        if lte_ul_cell_ids is not None:
            self._input_cell_ids(self._LTE_UL_CELL_IDS, lte_ul_cell_ids)

        if lte_dl_cell_ids is not None:
            self._input_cell_ids(self._LTE_DL_CELL_IDS, lte_dl_cell_ids)

        self.click_enabled_element((By.XPATH, self._APPLY_CONFIGURATION_BUTTON_XPATH))
        self.wait_for_visibility_by_xpath(self._CONFIGURING_STATUS)
        self.wait_for_invisibility((By.XPATH, self._CONFIGURING_STATUS))
        return self.get_attribute_by_xpath(self._CONFIGURE_IQ_CAPTURE_STATUS, "title")

    def _select_enable_capture_on_option(self, enable_capture_on):
        select_enable_capture_on_xpath = self.ENABLE_CAPTURE_ON_RADIO_XPATH_TEMPLATE.format(enable_capture_on)
        elem = self.driver.find_element_by_xpath(select_enable_capture_on_xpath)
        self.driver.execute_script("arguments[0].click();", elem)

    def _configure_with_capture_on_event(self,
                                         capture_from,
                                         ul_subcell_index_list,
                                         dl_subcell_index_list,
                                         buffer_cycle,
                                         capture_frame_offset,
                                         radio_configurations,
                                         profile):

        self._select_capture_from_option(capture_from)

        if profile:
            self._choose_profile(profile)

        if ul_subcell_index_list:
            self._select_subcell_list(self._UL_SUBCELL, ul_subcell_index_list)

        if dl_subcell_index_list:
            self._select_subcell_list(self._DL_SUBCELL, dl_subcell_index_list)

        if buffer_cycle is not None:
            self._select_buffer_cycle(buffer_cycle)

        if capture_frame_offset is not None:
            self._input_capture_frame_offset(capture_frame_offset)

        if radio_configurations:
            self._configure_multiple_radios(radio_configurations)

    def _select_capture_from_option(self, capture_from):
        select_capture_from_xpath = self.CAPTURE_FROM_RADIO_XPATH_TEMPLATE.format(capture_from)
        elem = self.driver.find_element_by_xpath(select_capture_from_xpath)
        self.driver.execute_script("arguments[0].click();", elem)

    def _choose_profile(self, profile):
        self.select_element_from_dropdown_list_by_text_and_click(
            element_text=profile, button_locator=(By.XPATH, self.PROFILE_BUTTON_XPATH),
            option_locator=(By.XPATH, self.PROFILE_DROPDOWN_OPTION_XPATH))

    def _configure_radio(self, rmod, configurations):
        if configurations.get('Antenna list', None) is not None:
            elem = self.driver.find_element_by_xpath(self._RMOD_CONFIGURATIONS_XPATH.format(rmod, 'Antenna list'))
            self._scroll_elem_into_view(elem)
            self.select_element_from_dropdown_list_by_text_and_click(
                configurations['Antenna list'],
                (By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, 'Antenna list') + "//button"),
                (By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, 'Antenna list') + "//ul//span")
            )
        if configurations.get(self._PLUS_FORTY_FIVE_POLARIZATION, None) is not None:
            self._configure_polarization(rmod,
                                        self._PLUS_FORTY_FIVE_POLARIZATION,
                                        configurations.get(self._PLUS_FORTY_FIVE_POLARIZATION, None))

        if configurations.get(self._MINUS_FORTY_FIVE_POLARIZATION, None) is not None:
            self._configure_polarization(rmod,
                                        self._MINUS_FORTY_FIVE_POLARIZATION,
                                        configurations.get(self._MINUS_FORTY_FIVE_POLARIZATION, None))

        if configurations.get('Capture activity timer', None) is not None:
            self.insert_text_to_enable_element(
                (By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, "Capture activity timer") + "//input"),
                configurations['capture_activity_timer']
            )


class DiagnosticCheckPage(v25r2.diagnostic.DiagnosticCheckPage):

    def __init__(self, driver):
        super(DiagnosticCheckPage, self).__init__(driver)
        self._view_panel = DiagnosticCheckPageViewPanel(driver)


class DiagnosticCheckPageViewPanel(v25r2.diagnostic.DiagnosticCheckPageViewPanel):

    def _get_bts_diagnostic_check_report(self, module):  # noqa: C901
        expand_element = self.driver.find_element_by_xpath(self._REPORT_EXPAN_ICON.format(module))
        orientation = expand_element.get_attribute("ng-reflect-ng-class")
        if "down" in orientation:
            expand_element.click()

        title = [elem.text for elem in self.driver.find_elements_by_xpath(self._TITLE.format(module))]
        while title and title[-1] == '':
            title.pop()

        total_trs = len(self.driver.find_elements_by_xpath(self._BODY_TR.format(module)))
        content = []
        for index in range(1, total_trs + 1):
            columns = self._get_content_from_table_line(self._BODY_TR.format(module) + '[{}]//td'.format(index))
            if not columns:
                continue

            while columns and columns[-1] == '':
                columns.pop()
            content.append(columns)

        num = len(content[0])
        if len(content[0]) == 1 and content[0][0] == self.NO_DATA_AVAILABLE:
            content[0] = content[0] * len(title)

        for index, item in enumerate(content):
            if len(item) == num:
                first_filed = content[index][0]
            elif len(item) < num:
                item.insert(0, first_filed)

        outcome = []
        for item in content:
            outcome.append(dict(zip(title, item)))

        return outcome
